import platform
from typing import List

def split(s: str, platform: str = 'this') -> List[str]:
    """
    Split the input str under given platform, return the splitting result.
    If platform equals 'this', auto-detect current platform.
    If platform equals '1', use POSIX style.
    If platform equals '0', use Windows/CMD style.

    Args:
        s: input str (str)
        platform: 'this' = auto from current platform (str);
                  '1' = POSIX (str);
                  '0' = Windows/CMD (str)

    Returns:
        a list of splitting str (List[str])
    """
    # Determine the delimiter based on the platform
    if platform == 'this':
        current_platform = platform.system()
        if current_platform == 'Windows':
            delimiter = '\\'
        else:
            delimiter = '/'
    elif platform == '1':
        delimiter = '/'
    elif platform == '0':
        delimiter = '\\'
    else:
        raise ValueError("Invalid platform specified. Use 'this', '1', or '0'.")

    # Handle edge case for empty string
    if not s:
        return []

    # Split the string using the determined delimiter
    return s.split(delimiter)

